"""Protocol fixtures were generated by the existing gear_sonic reference sender."""

import json
from pathlib import Path

import numpy as np
import pytest

from g1_pico_teleop.body.manager_wire import (
    HEADER_SIZE, MAX_MESSAGE_SIZE, ManagerWireError, decode_manager_message,
)


DATA = Path(__file__).parent / "data"


def pack(topic, arrays, version=None):
    types = {"float32": "f32", "float64": "f64", "int32": "i32", "int64": "i64",
             "uint8": "u8", "bool": "bool"}
    header = {"v": version or (1 if topic == b"command" else 3), "endian": "le", "count": 1,
              "fields": [{"name": name, "dtype": types[str(array.dtype)], "shape": list(array.shape)}
                         for name, array in arrays.items()]}
    return topic + json.dumps(header).encode().ljust(HEADER_SIZE, b"\0") + b"".join(
        array.tobytes() for array in arrays.values())


def poses(start=40, count=5, stamp=12345.0):
    return {
        "frame_index": np.arange(start, start + count, dtype=np.int64),
        "smpl_pose": np.arange(count * 63, dtype=np.float32).reshape(count, 21, 3) / 1000,
        "smpl_joints": np.arange(count * 72, dtype=np.float32).reshape(count, 24, 3) / 2000,
        "body_quat_w": np.tile(np.array([2**-0.5, 0, 0, 2**-0.5], dtype=np.float32), (count, 1)),
        "joint_pos": np.zeros((count, 29), dtype=np.float32),
        "joint_vel": np.zeros((count, 29), dtype=np.float32),
        "timestamp_monotonic": np.array([stamp], dtype=np.float64),
    }


def test_reference_sender_fixtures():
    topic, window = decode_manager_message((DATA / "manager_pose_v3.bin").read_bytes())
    assert topic == b"pose"
    np.testing.assert_array_equal(window.frame_index, [40, 41, 42, 43, 44])
    assert window.smpl_pose[4, 20, 2] == pytest.approx(0.314)
    assert window.smpl_joints[4, 23, 2] == pytest.approx(0.1795)
    np.testing.assert_allclose(window.body_quat_w[0], [2**-0.5, 0, 0, 2**-0.5])
    assert window.source_stamp == 12345.0
    assert decode_manager_message((DATA / "manager_off_v3.bin").read_bytes()) == (b"manager_state", 0)
    assert decode_manager_message((DATA / "manager_stop_v1.bin").read_bytes()) == (b"command", True)


@pytest.mark.parametrize("fault", ["shape", "nan", "zero_quaternion", "duplicate_index",
                                  "descending_index", "negative_index", "float_index",
                                  "oversized_window", "timestamp", "overflow", "missing_pose"])
def test_reject_invalid_poses(fault):
    arrays = poses()
    if fault == "shape": arrays["smpl_pose"] = np.zeros((5, 63), dtype=np.float32)
    if fault == "nan": arrays["smpl_joints"][0, 0, 0] = np.nan
    if fault == "zero_quaternion": arrays["body_quat_w"][0] = 0
    if fault == "duplicate_index": arrays["frame_index"][1] = arrays["frame_index"][0]
    if fault == "descending_index": arrays["frame_index"] = arrays["frame_index"][::-1]
    if fault == "negative_index": arrays["frame_index"][0] = -1
    if fault == "float_index": arrays["frame_index"] = arrays["frame_index"].astype(np.float32)
    if fault == "oversized_window": arrays = poses(count=65)
    if fault == "timestamp": arrays["timestamp_monotonic"][0] = -1
    if fault == "overflow": arrays["smpl_pose"] = np.full((5, 21, 3), 1e100, dtype=np.float64)
    if fault == "missing_pose": del arrays["smpl_pose"]
    with pytest.raises(ManagerWireError):
        decode_manager_message(pack(b"pose", arrays))


@pytest.mark.parametrize("fault", ["short", "trailing", "big", "endian", "version", "padding", "duplicate_field", "dimensions", "dtype"])
def test_reject_invalid_envelopes(fault):
    message = pack(b"pose", poses())
    header = json.loads(message[4:4 + HEADER_SIZE].rstrip(b"\0"))
    if fault == "short": message = message[:-1]
    elif fault == "trailing": message += b"X"
    elif fault == "big": message = b"X" * (MAX_MESSAGE_SIZE + 1)
    elif fault == "padding": message = message[:4 + HEADER_SIZE - 1] + b"X" + message[4 + HEADER_SIZE:]
    else:
        if fault == "endian": header["endian"] = "be"
        if fault == "version": header["v"] = 4
        if fault == "duplicate_field": header["fields"][1]["name"] = header["fields"][0]["name"]
        if fault == "dimensions": header["fields"][0]["shape"] = [2**63]
        if fault == "dtype": header["fields"][0]["dtype"] = "object"
        message = b"pose" + json.dumps(header).encode().ljust(HEADER_SIZE, b"\0") + message[4 + HEADER_SIZE:]
    with pytest.raises(ManagerWireError):
        decode_manager_message(message)


def test_optional_joint_fields_and_float64_input():
    arrays = poses()
    del arrays["joint_pos"], arrays["joint_vel"]
    arrays["smpl_pose"] = arrays["smpl_pose"].astype(np.float64)
    _, window = decode_manager_message(pack(b"pose", arrays))
    assert window.joint_pos.shape == (5, 29)
    assert not np.any(window.joint_pos)
    assert not np.any(window.joint_vel)


@pytest.mark.parametrize("mode", [-1, 6, 999])
def test_unknown_modes_rejected(mode):
    with pytest.raises(ManagerWireError):
        decode_manager_message(pack(b"manager_state", {"stream_mode": np.array([mode], dtype=np.int32)}))
